import { item } from "./items";
import type { PracticeBank } from "./items";

export const architectBank: PracticeBank = {
  practice: [
    item("lost-item-loop", "1.1", "stop", "Payments support agent",
      "A support agent calls `get_transaction` and the payment ledger throws `LedgerTimeout` after 5 s. The harness catches the exception and appends a user message reading 'The lookup failed, please continue.' The next API call returns `400 invalid_request_error`, and 2.3% of conversations end this way. The ledger usually recovers within a minute. What should the harness send instead?",
      "b", "Every tool_use block must be answered by a tool_result with the same tool_use_id in the next user message, even when the tool fails. Report failures with is_error: true and a clear description so Claude can recover; plain-text notes, removed turns and fake empty results break the protocol or mislead the model.",
      ["Drop the failed assistant turn from history and call the API again so Claude can choose a different tool.", "Deleting the assistant turn hides that the lookup was attempted, and Claude may repeat the call without knowing it failed."],
      ["A user message with a `tool_result` for that `tool_use_id`, setting `is_error: true` and describing the timeout.", "Every tool_use needs a matching tool_result; marking it as an error lets Claude explain the delay or retry instead of the request failing."],
      ["A `tool_result` for that ID containing an empty transaction list, so the conversation continues without an error state.", "An empty list tells Claude the transaction does not exist, so it may give the customer a false answer about the charge."],
      ["A retry of `get_transaction` inside the harness until the ledger responds, before sending anything back to the API.", "Unbounded retries can hold the turn open for a minute or more, and the customer gets no explanation while the harness waits."]),
    item("archive-missing-slice", "1.2", "research", "Market research coordinator",
      "A research coordinator splits 'EV battery supply risks' across three subagents: lithium mining, cell manufacturing and recycling. Two return complete findings. The recycling subagent returns findings for Europe and North America plus `uncovered: [\"Asia-Pacific\"]` after its search budget ran out. The brief requires all three regions. What should the coordinator do next?",
      "c", "When a subagent reports a specific coverage gap, the coordinator should keep verified work and re-delegate only the missing slice with its own budget and explicit scope. Rerunning everything wastes effort, extrapolation invents coverage, and dropping the topic discards valid findings.",
      ["Re-run all three subagents with larger search budgets so every topic is researched again with more depth.", "Two topics are complete; rerunning them wastes budget, and the reported gap is one region in one topic."],
      ["Have the synthesis subagent extrapolate Asia-Pacific recycling risks from the European and North American findings it has.", "Extrapolation fills a reported gap with inference, so the report would claim regional coverage it does not have."],
      ["Keep all returned findings and dispatch a recycling subagent scoped only to Asia-Pacific with its own search budget.", "This keeps completed work and assigns exactly the uncovered slice the subagent reported, satisfying the three-region requirement."],
      ["Publish now with the two complete topics and omit recycling, since its coverage is incomplete for the brief.", "Dropping the recycling topic discards valid findings for two regions and still fails the brief's coverage requirement."]),
    item("two-workers", "1.3", "subagents", "Vendor contract review",
      "A coordinator delegates two independent reviews of a vendor contract: one subagent checks data-protection clauses against `dpa_index`, the other checks pricing against `rate_cards`. Traces show each subagent spent its first 6 turns asking which contract and which version to review, and the pricing subagent also queried `dpa_index` 14 times. Which two changes fix these problems?",
      "ad", "Subagents begin with only the prompt and tools the coordinator gives them. Put every needed fact, such as IDs, versions and output format, in the task prompt, scope each subagent's tools to its job, and launch independent subagents together. Shared history, broader tools or bigger turn limits do not fix context gaps.",
      ["Put the contract ID, version and expected citation format directly in each subagent's task prompt from the coordinator.", "Subagents start with only their own prompt, so stating the contract and version removes the six turns spent rediscovering them."],
      ["Let each subagent read the coordinator's full conversation history so it can find the contract details itself.", "Subagents do not inherit the parent's history, and passing the whole transcript adds noise instead of the two facts they need."],
      ["Give both subagents both indexes so either one can cross-check the other's findings when it finishes early.", "Wider tool access is what let the pricing subagent wander into dpa_index; it breaks the separation between the two reviews."],
      ["Set each AgentDefinition's `tools` list to its own index, and spawn both subagents in the same coordinator turn.", "Scoped tool lists keep each review on its own source, and issuing both Agent calls together runs the independent reviews in parallel."],
      ["Raise each subagent's `maxTurns` from 10 to 25 so it has room to clarify the task before reviewing.", "More turns pay for the clarification instead of removing it, and do nothing about the pricing subagent's off-scope queries."]),
    item("refund-order", "1.4", "agents", "Billing support agent",
      "A billing agent can call `verify_identity`, `get_invoice` and `issue_credit`. Policy requires identity verification within the current session before any credit. Traces show 4% of credits were issued in resumed sessions where the summary said 'customer verified yesterday', and 2 of those went to the wrong account. What change most reliably enforces the ordering?",
      "a", "When an ordering rule protects money or identity, enforce it in code at the point of action. A PreToolUse hook or tool-layer check that refuses the downstream call until the prerequisite has succeeded in the current session gives a deterministic guarantee; prompts and examples only make violations rarer.",
      ["A PreToolUse hook that denies `issue_credit` unless `verify_identity` succeeded for that account in the current session.", "The hook checks session state before the credit executes, so a summary's claim about yesterday cannot satisfy the requirement."],
      ["A system prompt rule stating that verification must be repeated in every resumed session before issuing a credit.", "Prompt rules make the skip less frequent but not impossible, and the 2 wrong-account credits show misses are costly."],
      ["Few-shot examples showing the agent calling `verify_identity` first, even when a summary mentions an earlier verification.", "Examples improve the habit probabilistically; the agent can still trust a summary and skip verification in some sessions."],
      ["A PostToolUse hook on `issue_credit` that checks verification afterward and alerts a supervisor about any gap.", "Checking after the credit executes detects the violation once money has moved, rather than preventing the credit."]),
    item("two-hooks", "1.5", "hooks", "Infrastructure repository",
      "A team wants Claude Code to block any `Bash` command containing `terraform apply` in the repository. They added `.claude/hooks/block-apply.sh` as a PreToolUse command hook in `.claude/settings.json`. The script prints 'blocked' and exits with code 1, yet 3 applies still ran this week. What change makes the hook block the call?",
      "b", "Claude Code command hooks communicate through exit codes and JSON. For PreToolUse, exit code 2 blocks the tool call and returns stderr to Claude, or the hook can print a permissionDecision of deny. Other non-zero codes are non-blocking errors, and PostToolUse runs too late to prevent an action.",
      ["Move the script to a PostToolUse hook so it runs after the command and can report the blocked apply.", "PostToolUse runs after the command has executed, so terraform apply would already have changed infrastructure."],
      ["Exit with code 2 and write the reason to stderr, or print `permissionDecision: \"deny\"` JSON and exit 0.", "Exit code 2 is the blocking code and sends stderr back to Claude; the JSON deny decision is the structured alternative."],
      ["Keep exit code 1 and add 'never run terraform apply' to the project CLAUDE.md as a second safeguard.", "Exit code 1 is a non-blocking error, so the call proceeds; the CLAUDE.md line is guidance that Claude can still miss."],
      ["Register the script under a `blockingHooks` key in `.claude/settings.json` so non-zero exits stop the call.", "There is no blockingHooks setting; blocking behavior comes from exit code 2 or a deny decision in the hook's output."]),
    item("old-payment-module", "1.6", "agents", "Invoice migration",
      "A team must migrate invoice generation from a legacy billing module to a new service in three known stages: data export, template port and cutover. The legacy module has no documentation, and an earlier attempt found 3 hidden callers only after release. The release review must catch both per-file defects and cross-module contract breaks. How should the work be decomposed?",
      "c", "Decompose with fixed structure where the work is understood and adaptive discovery where it is not. Use known stages as a scaffold, add investigation for undocumented dependencies, and include both local and cross-module review passes, because per-file checks cannot see integration breaks.",
      ["Fix every subtask in a detailed plan up front and review each changed file in isolation before cutover.", "A fixed plan cannot account for callers nobody has found yet, and file-by-file review misses cross-module contract breaks."],
      ["Give one session the whole migration in a single prompt and ask for one long final report documenting and reviewing every change made.", "One undifferentiated task leaves caller discovery and integration checks implicit; a report describing changes does not find the hidden callers."],
      ["Use the three stages as a scaffold, add a caller-discovery step for the legacy module, then run per-file and integration reviews.", "Known stages give structure, discovery addresses the undocumented module, and the two review passes catch both defect classes the release needs."],
      ["Have three subagents each propose a full migration independently and adopt the proposal with the most detail.", "Detail is not evidence of correct dependency coverage, and none of the proposals is required to find the hidden callers."]),
    item("branch-investigation", "1.7", "sessions", "Outage investigation",
      "During an outage review, an engineer's Claude Code session `outage-0412` holds 90 minutes of verified log analysis. She wants to try two remediation scripts from that point; neither attempt should see the other's turns, and the incident lead will resume `outage-0412` tomorrow expecting it unchanged. Both scripts edit the same files. Which workflow fits?",
      "d", "Forking separates conversation history, but not files on disk. To compare alternatives from one verified baseline, fork the session once per alternative so the original stays intact, and give each fork its own working tree, for example a git worktree, when the alternatives edit the same files.",
      ["Resume `outage-0412` and try both scripts one after the other, reverting files with git between attempts.", "Both attempts append to outage-0412, so the lead's session changes and the second attempt inherits the first one's turns."],
      ["Start two fresh sessions in separate worktrees and ask each to redo the log analysis before remediating.", "Isolation is achieved, but 90 minutes of verified analysis is thrown away and must be rediscovered twice."],
      ["Run `/compact` in `outage-0412`, then fork it once and try both scripts in that single forked session.", "Compaction alters the lead's session, and a single fork means the two attempts share one history instead of staying independent."],
      ["Run `claude --resume outage-0412 --fork-session` once per script, each fork in its own git worktree.", "Each fork gets its own session ID from the verified history, and separate worktrees keep the two scripts' file edits apart."]),
    item("lookup-and-book", "2.1", "tool", "Insurance claims agent",
      "A claims agent connects two MCP servers that each expose a tool named `search`: `mcp__claims__search` described as 'Search records' and `mcp__kb__search` described as 'Search documents'. In 500 logged conversations, 22% of claim-status questions went to the knowledge-base tool, which returned policy articles instead of claim records. What is the most effective first step?",
      "b", "Tool descriptions are the primary mechanism Claude uses to pick a tool, and same-named tools from different MCP servers make vague descriptions worse. First write descriptions that state purpose, accepted inputs, example queries and when to use the alternative; add routing or restructuring only if clear descriptions do not fix selection.",
      ["Rename the tools to `search_claims` and `search_articles` on each server while keeping their current one-line descriptions.", "Better names help a little, but descriptions still omit inputs, outputs and when to prefer the other tool, so ambiguity remains."],
      ["Rewrite each description to state what it searches, its ID formats, example queries, and when to use the other tool.", "Descriptions are the main selection signal; stating scope, inputs and boundaries addresses why claim questions reach the knowledge base."],
      ["Add a routing layer that sends any message containing a claim number pattern straight to `mcp__claims__search`.", "A regex router is a heavy first step that bypasses model judgment and misroutes questions that mention a claim but need policy text."],
      ["Disconnect the knowledge-base server and paste its ten most-used articles into the agent's system prompt instead.", "Removing the server loses access to the rest of the knowledge base and inflates every prompt, instead of clarifying the tools."]),
    item("two-failure-layers", "2.2", "mcp", "Warehouse inventory agent",
      "An inventory agent checks three warehouses. Warehouse A's `check_stock` result is `isError: false` with `items: []`. Warehouse B's result is `isError: true` with `errorCategory: \"unavailable\"` after its database went offline. For warehouse C, the MCP connection drops after 30 s and no result arrives. The draft reply says 'none of the three warehouses has stock'. How should the report describe the three?",
      "c", "Keep three outcomes distinct: a completed search that found nothing is evidence of absence; isError: true means the tool ran and failed; a dropped connection means no result exists at all. Collapsing them into 'no stock' turns failures into false negatives and hides which locations still need checking.",
      ["A and C have no stock because neither returned items, and B is offline and should be checked again later.", "C never returned a result, so its stock is unknown; treating silence as an empty answer repeats the draft's error for C."],
      ["All three are tool execution errors, so retry them together and report stock only after every one of the calls succeeds.", "A completed successfully, and C failed at the transport layer without a tool result, so neither is a tool execution error."],
      ["A was checked and has none, B failed at the tool with a database outage, and C is unchecked after a disconnect.", "Each warehouse keeps the meaning of its evidence: a completed empty search, an execution error, and a transport failure with no result."],
      ["Report only B as a problem because it is the one result carrying an error payload, and A and C as empty.", "Only A's empty result is a verified answer; C's lost connection is a coverage gap that the report must disclose."]),
    item("cross-role-tool", "2.3", "tool", "Escalation desk agents",
      "A triage agent needs the status of one escalated case per conversation; 30% of its turns currently hand control back to the supervisor agent just to read status, adding 2.4 s each. The supervisor agent holds 9 case-management tools, including `update_case` and `close_case`. Triage must never modify cases or see other customers' records. What should triage receive?",
      "a", "When a role frequently needs one narrow capability outside its specialty, give it a small, constrained tool rather than the full toolset or a workaround. Scope the tool to the exact operation and have the backend enforce record access, so least privilege holds even if the model errs.",
      ["A narrow `get_case_status` tool returning status only, with the service checking the case belongs to the caller.", "A constrained cross-role tool removes the round trip for the common need while the service enforces the record boundary."],
      ["The supervisor's full set of 9 tools, with a system prompt telling triage to use only the read methods among them.", "This grants update and close capability and relies on the prompt to prevent misuse, violating least privilege."],
      ["`tool_choice` forcing `update_case` with an empty body, which returns the current case as a side effect.", "Calling a write tool to read data keeps write access in triage's hands and still lacks any per-customer record check."],
      ["A nightly export of every escalated case so triage can look up the status locally without calling tools.", "The export exposes other customers' cases to triage and is up to a day stale for a status question."]),
    item("connector-scope", "2.4", "mcpConfig", "Issue tracker integration",
      "Everyone on a repository needs the shared `jira` MCP server. One developer is also trying an experimental `perf-traces` server that teammates should not get. Each person authenticates to Jira with their own token, which must not reach git. The developer currently has both servers in `~/.claude.json` under user scope. Which two configuration choices fit?",
      "be", "Choose MCP scope by who should get the server. Project scope in a committed `.mcp.json` shares it with every clone, using `${VAR}` for secrets. Local scope suits one person's experiment in one project; user scope follows one person everywhere. Both personal scopes live in `~/.claude.json`.",
      ["Commit both servers to `.mcp.json` with the developer's Jira token inline so every clone works on first run.", "This leaks a personal token into git history and pushes the experimental server onto every teammate."],
      ["Add `jira` to the committed `.mcp.json` with its token written as `${JIRA_TOKEN}` from each person's environment.", "Project scope shares the server with every clone, and environment expansion keeps each person's token out of the repository."],
      ["Keep `jira` in user scope and add its URL to CLAUDE.md so teammates know to configure the same server.", "User scope is personal; a CLAUDE.md note is documentation, so each teammate still has to add the server manually."],
      ["Declare both servers in `.claude/settings.json` under an `mcpServers` key with `scope: \"local\"` for the experiment.", "Claude Code reads shared MCP servers from `.mcp.json`, and scopes are chosen with `claude mcp add --scope`, not a settings key."],
      ["Add `perf-traces` with `claude mcp add --scope local`, keeping it in `~/.claude.json` for this project only.", "Local scope, the default for claude mcp add, applies to this project for this developer alone, so teammates never receive it."]),
    item("exact-edit", "2.5", "cli", "Billing sync service",
      "The agent must change the retry limit in one call, `retry(fetchInvoice, 3)`, inside `billing/sync.ts`. Its Edit call fails because `old_string` is not unique: it matches 4 locations. The other three matches, in different functions, must stay at 3. A previous workaround used Write and dropped two exports from the 1,800-line file. What should the agent do next?",
      "d", "Edit replaces an exact old_string and refuses when it is not unique, which protects against unintended changes. Make the match unique by including surrounding context, or use replace_all only when every occurrence should change. Full-file Write and unaddressed shell substitutions trade that safety for risk.",
      ["Retry Edit with `replace_all: true`, then manually restore the three other calls to 3 with further Edit calls.", "replace_all changes all four matches, creating three wrong edits that must be undone, which is more risk than needed."],
      ["Rewrite the whole file with Write, copying its current contents and changing only the one call by hand.", "Full-file Write is what previously dropped exports; reproducing 1,800 lines to change one argument invites the same loss."],
      ["Run a `sed -i` substitution through Bash on `retry(fetchInvoice, 3)` so the call changes in place.", "Without an address, sed changes every matching line, so the three calls that must stay at 3 would change too."],
      ["Read the function, then retry Edit with an `old_string` that includes enough nearby lines to be unique.", "Edit requires a unique old_string unless replace_all is set; adding the enclosing function's context isolates the one call safely."]),
    item("shared-workspace-rule", "3.1", "memory", "Checkout web repository",
      "A developer keeps three instructions in the repository's committed `CLAUDE.md`: the team's 'run `pnpm build:affected` before committing', her local sandbox URL `http://localhost:4012`, and her preference for brief explanations in every project. Teammates' sessions keep trying her port and hit 6 failed connections this week. How should the three instructions be placed?",
      "c", "Match each instruction to its audience. Project `CLAUDE.md` is committed and shared; `CLAUDE.local.md` holds personal notes for one project and should be gitignored; `~/.claude/CLAUDE.md` holds personal preferences for every project. Path-scoped rules select by file pattern, not by person.",
      ["Keep all three in project `CLAUDE.md`, labeling the sandbox URL and style lines as applying to her alone.", "Labels do not stop the lines loading for everyone, so teammates still receive her port and her style preference."],
      ["Move all three to her `~/.claude/CLAUDE.md` so that personal and team instructions are managed together in one place.", "Teammates would lose the build convention entirely, since user-level files are never shared through the repository."],
      ["Build rule in project `CLAUDE.md`, sandbox URL in gitignored `CLAUDE.local.md`, and style in `~/.claude/CLAUDE.md`.", "Each instruction lands at the scope it applies to: the team, her work in this project only, and her work everywhere."],
      ["Move the sandbox URL and style line into `.claude/rules/personal.md` with `paths` matching her own files.", "Rules in .claude/rules are committed and match file paths, not people, so teammates editing the same files still load them."]),
    item("publish-skill", "3.2", "skills", "Release engineering",
      "Release engineers run a 15-step pre-release checklist that references three example config files. It must be invocable as `/pre-release`, versioned with the repository, and reviewed like code. Currently it lives as a pasted note, and 4 of the last 10 releases skipped steps. Which packaging fits?",
      "a", "Package a repeatable team procedure as a project skill under `.claude/skills/<name>/SKILL.md`, or a command under `.claude/commands/`. Skills add the ability to bundle supporting files in the same folder. Both are versioned with the repository; user files, settings permissions and invented config files are not procedures.",
      ["A project skill at `.claude/skills/pre-release/SKILL.md`, with the three example configs stored beside it in that folder.", "A project skill is versioned with the repo, invocable by name, and can bundle the supporting files the checklist references."],
      ["The checklist pasted into each release engineer's `~/.claude/CLAUDE.md`, with the example configs attached to a wiki page.", "User-level instructions are not shared or reviewed through the repository, and they load in every session rather than on demand."],
      ["A `.claude/config.json` entry named `pre-release` whose `steps` array lists the checklist and the config file paths.", "Claude Code has no `.claude/config.json` command registry, so this would never create a `/pre-release` entry."],
      ["Permission allow rules in `.claude/settings.json` for each checklist command, with the examples listed in comments.", "Permission rules control which tools may run without prompting; they do not define a named, invocable procedure."]),
    item("cross-tree-tests", "3.3", "memory", "Payments monorepo",
      "Database tests live in three packages, for example `packages/orders/test/db/refund.db.test.ts` and `packages/ledger/test/db/post.db.test.ts`. A migration-safety rule should load when Claude edits any `*.db.test.ts` file and stay out of context for application code. Copies in each package's `CLAUDE.md` loaded during 70% of non-test sessions last week. What should the team commit?",
      "d", "Path-specific rules in `.claude/rules/` load only when Claude reads or edits a file matching their `paths` globs, which are resolved from the project root. They suit conventions tied to a file pattern across many directories, where root CLAUDE.md is always loaded and directory files must be duplicated.",
      ["One copy of the rule in root `CLAUDE.md`, asking Claude to apply it only when editing database test files.", "The root file loads in every session, so the rule still occupies context during application work and depends on inference."],
      ["A `CLAUDE.md` inside each `test/db/` folder, so the rule loads only when Claude works in those directories.", "Directory files would work for today's three folders, but they must be duplicated and kept in sync as packages are added."],
      ["A `.claude/skills/db-tests/SKILL.md` holding the rule, with a description saying it applies to every database test file.", "A skill loads when invoked or selected by Claude, not automatically when a matching file is edited."],
      ["Commit one `.claude/rules/db-tests.md` file with `paths: [\"**/*.db.test.ts\"]` in its frontmatter, covering all three packages.", "A path-scoped rule loads only when Claude touches a file matching the glob, in any package, with one copy to maintain."]),
    item("unknown-impact", "3.4", "settings", "Checkout web repository",
      "Two requests arrive in one session. The first changes a button label in `CheckoutButton.tsx`, a single-file change with a passing snapshot test. The second replaces the `customerRef` identifier used by 3 undocumented services, estimated at 30+ files. The engineer is mid-session in default permission mode. Which working approach fits both?",
      "b", "Choose the mode per task. Small, well-understood changes run directly; large or uncertain changes, such as an identifier used by undocumented services, start in plan mode, entered with Shift+Tab, `/plan` or `--permission-mode plan`. Planning trivial edits wastes review cycles, and failure-driven discovery defers risk.",
      ["Prefix both requests with `/plan` so each gets a reviewed plan before any file is edited.", "Planning a one-file label change adds an approval cycle with no risk reduction; plan mode is for the uncertain migration."],
      ["Make the label change directly, then press Shift+Tab into plan mode to map the services before the migration.", "Direct execution suits the scoped label fix, and plan mode lets Claude explore the undocumented services before proposing edits."],
      ["Make both changes directly and rely on CI to surface any service that still reads `customerRef` after the merge.", "Using CI failures as discovery repeats the risk plan mode exists to avoid when consumers are undocumented."],
      ["Restart the session with `claude --plan-only` so both changes are planned without risk of accidental edits.", "`--plan-only` is not a Claude Code flag; plan mode is entered with Shift+Tab, `/plan`, or `--permission-mode plan`."]),
    item("null-fixture", "3.5", "eval", "Data import pipeline",
      "Claude's fix to `normalizeDate()` now handles valid dates, but the import job still crashes on `null` and turns `\"\"` into `1970-01-01`, corrupting 212 rows last night. Both inputs pass through the same function, used by 6 callers. The engineer is about to reply 'please handle edge cases better'. What feedback should the engineer give instead?",
      "c", "Iterative refinement works best with concrete input-output examples at the right boundary. Write the failing cases as tests with expected results at the shared function, then fix and run them. Vague adjectives, raw logs, caller-level patches and rewrites leave the contract unstated or the defect duplicated.",
      ["Ask Claude to add null and empty-string guards in each of the 6 callers, with one test per caller.", "Patching callers duplicates handling six times and leaves the shared function's contract undefined, so new callers inherit the bug."],
      ["Paste last night's 4,000-line import log and ask for a more defensive implementation, reviewed across the module.", "The log buries the two failing inputs and 'more defensive' states no expected output, so the fix remains a guess."],
      ["Give `null → null` and `\"\" → null` as test cases with expected outputs, ask Claude to add them, then fix and run.", "Concrete input-output pairs define the missing contract at the shared function, and tests make the fix verifiable before rerunning the import."],
      ["Ask Claude to rewrite `normalizeDate()` using a date library, since the current hand-written parser keeps failing.", "A library swap may change valid-date behavior that now works, and still leaves the null and empty-string outputs unspecified."]),
    item("ci-review", "3.6", "cli", "Pull-request pipeline",
      "The PR job runs `claude -p \"Review this PR and run the unit tests\" --output-format json`. In 40 of 40 runs, the transcript shows the `Bash(npm test)` call was denied for lack of permission, so reviews never include test results. The job must not be able to push, delete files or call the network. Which change fits?",
      "a", "Headless runs cannot answer permission prompts, so pre-approve exactly the tools a CI job needs with `--allowedTools`, using patterns such as `Bash(npm test *)`. Broad bypasses violate least privilege, permission modes target different tool classes, and invented environment variables do nothing.",
      ["Add `--allowedTools \"Read\" \"Grep\" \"Bash(npm test *)\"` so only the test command runs without a prompt.", "Pre-approving the exact test command and read tools lets the review run tests while other Bash commands remain unapproved and denied."],
      ["Add `--dangerously-skip-permissions` so the headless job never stops on a permission check for any tool.", "Skipping all permission checks lets the job push, delete or reach the network, which the requirements explicitly forbid."],
      ["Add `--permission-mode acceptEdits` so Claude can run the tests without approval during the review job.", "acceptEdits auto-approves file edits, not shell commands, so npm test is still denied and the review can now modify files."],
      ["Set `CLAUDE_CI=1` in the job environment so Claude Code applies its built-in CI permission profile.", "There is no CLAUDE_CI variable or built-in CI permission profile; tool permissions are granted with --allowedTools or settings."]),
    item("review-criteria", "4.1", "prompt", "Currency code review",
      "An automated reviewer flagged rounding in 120 of 400 pull requests last month; 104 of those used `roundHalfEven()` as documented in `MONEY.md`, which allows it for currency. Developers now dismiss 80% of its comments, including some real defects. The prompt says 'flag suspicious rounding'. What prompt change should the team test first?",
      "b", "Reduce false positives with categorical criteria tied to documented standards, not with strictness or confidence wording. State exactly what counts as a finding, reference the rule, and show a compliant and a violating example. Self-rated confidence and blanket suppression trade precision for missed defects.",
      ["Tell the reviewer to be less strict about rounding and to comment only when it is highly confident of a bug.", "Leniency and confidence give no rule, so legitimate roundHalfEven uses may still be flagged and real defects suppressed."],
      ["Flag rounding only when it departs from `MONEY.md`'s rule, with one compliant and one violating example.", "An explicit criterion tied to the documented rule, illustrated on both sides, removes the 104 false positives and keeps real violations."],
      ["Have the reviewer attach a confidence score to each comment and post only the top quarter by score.", "Self-assessed confidence is not calibrated to the documented rule, so dropping low scores removes comments arbitrarily."],
      ["Temporarily disable all rounding comments until the team agrees on a better review model for the job.", "Disabling the category hides real rounding defects in the meantime, and a different model still lacks the missing criterion."]),
    item("two-edge-examples", "4.2", "prompt", "Procurement quote extraction",
      "A quote-extraction prompt works on firm prices but labels 31% of rough figures, such as 'approx. $1,200' or 'est. 900–1,100', as `amount_type: \"firm\"`. Procurement auto-approves firm quotes under $2,000. The prompt has room for two more examples. Which pair is most useful?",
      "d", "Use few-shot examples to teach the boundary the model gets wrong. A minimal pair that differs only in the deciding cue, each with its exact target output, is the most efficient use of limited slots; examples of cases already handled, unrelated variety or unlabeled inputs teach nothing new.",
      ["Two quotes with clearly printed firm prices, each labeled with the amount and `amount_type: \"firm\"` as the target.", "Firm prices already extract correctly, so both slots rehearse a case that is not failing."],
      ["One quote with twelve line items and one spanning three pages, both labeled with firm totals.", "These add variety on length and layout, unrelated to the estimate-versus-firm boundary behind the 31% error rate."],
      ["Two estimate quotes shown as raw text with no labeled output, plus a prompt note that estimates need careful review before labeling.", "Without target outputs, the examples do not show which amount_type to emit, so the boundary is still untaught."],
      ["A quote reading 'approx. $1,200' labeled `amount_type: \"estimate\"`, paired with one reading '$1,200 firm' labeled `\"firm\"`.", "A minimal contrasting pair with the same figure isolates the hedging language that decides the label, directly targeting the failure."]),
    item("schema-and-policy", "4.3", "structured", "Supplier intake extraction",
      "A supplier-intake extractor must return `status` from the enum `received | partial | rejected` and `ship_date` as a date or null. Downstream, 3% of records fail because `ship_date` precedes the purchase-order date stored in the ERP. The model supports strict structured outputs. Which two controls are required?",
      "ac", "Structured outputs and schemas enforce shape: types, required fields and enums. Business rules that depend on external, trusted data, such as dates in an ERP, need a separate validation step in code. Use both layers, and do not rely on the model's self-assessment for either.",
      ["A strict JSON schema with the `status` enum and `ship_date` typed as a date string or null.", "Strict structured output constrains types, required keys and allowed status values at generation time for each record."],
      ["One formatted example in the prompt, accepting any response that contains both field names.", "Field presence does not guarantee the enum value or the date type, so malformed records still pass."],
      ["A code check comparing `ship_date` with the ERP purchase-order date before the record is accepted.", "The ordering rule depends on trusted ERP data the schema cannot see, so it needs a separate semantic validation."],
      ["A prompt asking Claude to confirm the ship date is plausible and accepting records when it answers yes.", "Self-assessment is not a deterministic check against the ERP date, so some early ship dates would still be accepted."],
      ["Encoding the purchase-order relationship in the JSON schema so structured outputs enforce it during generation.", "The schema has no access to each record's ERP date, so it cannot express a cross-record comparison like this."]),
    item("repair-versus-review", "4.4", "structured", "Accounts payable extraction",
      "A validator rejects two extracted invoices. On INV-881, `due_date` is `\"March 5th 2026\"` instead of ISO 8601, and the source is clear. On INV-902, the document states a total of $4,310 on page 1 and $4,130 on page 3. The original PDFs are available. Which recovery policy fits?",
      "a", "Distinguish errors that retries can fix from ones they cannot. A format or structure mistake with a clear source can be retried with the specific validation error. Information that is contradictory or absent in the source needs review; retrying, nulling or picking a value hides the problem.",
      ["Retry INV-881 with the validation error and target format, and send INV-902 to review citing both totals.", "Format errors are fixable with specific feedback, while contradictory totals in the source need a human decision, not another extraction."],
      ["Retry both invoices with the original prompt and no error details, accepting the first schema-valid response.", "Without feedback the retry may repeat the error, and a schema-valid total for INV-902 would hide the document's own contradiction."],
      ["Set both failing fields to null, accept the records, and document that two values failed validation.", "Nulling a clear due date discards recoverable data, and nulling the total hides a real discrepancy that someone must resolve."],
      ["Correct INV-881's date in code and post INV-902 with the larger total after confirming it against page 1.", "Code conversion suits the date, but picking the larger total invents a precedence rule for a genuine conflict in the source."]),
    item("permit-digest", "4.5", "batch", "Contract summarization",
      "Contracts arrive throughout the day and each must have an extracted summary within 30 hours of arrival. The team plans to submit one Message Batch per day at midnight to get the 50% discount. A contract arriving at 00:05 would wait almost 24 hours before submission. How often should batches be submitted?",
      "c", "Message Batches trade latency for a 50% discount: most finish quickly, but results are only guaranteed within 24 hours. Size submission frequency from the SLA minus that window, leaving slack for polling and resubmitting failures by custom_id. Typical completion times are not a guarantee.",
      ["Once daily at midnight is fine, because most batches complete within an hour, well inside the 30-hour target.", "Batches have no latency guarantee and can take up to 24 hours; 24 hours waiting plus 24 processing breaks the 30-hour target."],
      ["Every 12 hours, which halves the waiting time and still leaves room for the batch to finish.", "Up to 12 hours waiting plus up to 24 hours processing totals 36 hours, exceeding the 30-hour requirement."],
      ["Every 4 hours, so waiting plus the 24-hour processing window stays under 30 hours with time for resubmission.", "Four hours of waiting plus up to 24 hours of processing leaves about 2 hours for polling and resubmitting failures."],
      ["Submit each contract as its own batch immediately on arrival, polling every minute until its result is ready.", "Single-request batches still carry the 24-hour window, and per-request polling adds overhead without improving the guarantee."]),
    item("independent-integration-review", "4.6", "eval", "Order platform release",
      "The session that wrote a 14-file change also reviewed it, and its review passed. In production, `OrderService` sent amounts in cents while `InvoiceClient` expected dollars; the mismatch spanned two files reviewed separately. The authoring session's notes say 'units consistent'. Local tests pass at 96% coverage. Which review step best addresses this evidence?",
      "d", "A model reviewing its own work carries the same assumptions that produced the defect. Use an independent review instance without the generation reasoning, and target the failure layer: cross-file contracts need an integration pass. Self-review, file-isolated checks and self-reported confidence miss errors that live between modules.",
      ["Ask the authoring session to re-read its design notes and re-review and verify each file with more reasoning effort.", "The same session keeps its 'units consistent' assumption, and file-by-file review cannot see a mismatch between files."],
      ["Add a lint rule pass that validates numeric types in each changed file separately.", "Lint checks files individually and cannot know that cents and dollars disagree across a module boundary."],
      ["Review only the files the author marks as low confidence, so reviewer attention goes where risk is highest.", "The author was confident about units, so self-marked confidence would steer review away from the actual defect."],
      ["Run a separate review instance with no access to the author's notes over cross-module data flow and contracts.", "A fresh instance does not inherit the author's assumption, and an integration focus targets the boundary where cents met dollars."]),
    item("exact-dates", "5.1", "context", "Retail support agent",
      "Each `lookup_order` call returns about 3,500 tokens across 40 fields, of which the support agent uses 5: order ID, status, promised date, amount and return eligibility. After 12 lookups, the agent misquoted a promised date that appeared early in the conversation, and compaction triggers twice per long session. What change best preserves the critical facts?",
      "b", "Verbose tool outputs consume context and push critical facts into positions where they are lost or summarized away. Trim results to the fields the agent uses before they accumulate, and keep exact transactional facts in a structured block carried on each turn. Bigger windows and reminders do not remove the noise.",
      ["Switch to a model with a larger context window so all twelve full lookup results fit without compaction.", "A bigger window delays compaction, but 42,000 tokens of mostly irrelevant fields still bury the dates the agent misquotes."],
      ["Trim each lookup result to the 5 used fields in a PostToolUse hook, and keep them in a per-order facts block.", "Trimming removes 35 irrelevant fields before they accumulate, and a keyed facts block keeps each promised date exact across turns."],
      ["Add a system prompt instruction reminding the agent to re-read earlier tool results before quoting dates.", "Re-reading does not fix facts buried in a long context or already summarized away, so misquotes continue."],
      ["Call `lookup_order` again before every reply so the latest full result is always at the very end of the context.", "Repeated full lookups add 3,500 tokens each time, accelerating compaction and still mixing the key fields with noise."]),
    item("different-escalations", "5.2", "agents", "Appliance returns agent",
      "Case A asks the agent to match a competitor's price; the returns policy covers damage and late delivery but says nothing about price matching. Case B uses all-caps and profanity but requests a standard replacement for a damaged blender, with a photo attached, which policy covers. First-contact resolution is 58% against an 80% target. Which dispositions fit?",
      "c", "Escalate on case characteristics, not on emotion or self-rated confidence: explicit requests for a human, policy gaps or exceptions, and requests the agent cannot resolve. Resolve covered, routine requests even when the customer is upset, acknowledging the frustration, because unnecessary escalation lowers first-contact resolution.",
      ["Escalate B because the negative sentiment signals risk, and let the agent decide A's price match by itself.", "Sentiment does not measure case complexity, and approving A without a policy basis improvises an exception the agent is not authorized to make."],
      ["Escalate both, since one lacks a policy and the other is frustrated, to protect the 80% target.", "Escalating B's routine, covered replacement lowers first-contact resolution, which is the opposite of protecting the target."],
      ["Escalate A as a policy gap with a summary; resolve B's covered replacement and acknowledge the frustration.", "Policy silence is a real escalation trigger, while B's request is standard and covered, so resolving it raises first-contact resolution."],
      ["Have the agent rate its confidence on each case and escalate whichever case scores below 7 out of 10.", "Self-rated confidence is poorly calibrated and would not reliably separate the policy gap from the routine replacement."]),
    item("partial-research", "5.3", "research", "Regulatory research system",
      "The document analysis subagent returns `{\"status\": \"failed\"}` whenever any source fails. For 3 of 8 filings last week the real cause was `403 access_denied` from a paywalled archive; the coordinator retried each 5 times, adding 12 minutes, then reported the whole analysis as failed even though 5 filings were analyzed. What should the subagent return?",
      "d", "Propagate subagent errors with enough structure for the coordinator to choose a recovery: the error category, whether a retry can help, what was attempted, partial results and alternatives. Generic failure statuses cause wasted retries and discarded work; silent omission and run-ending exceptions are the two opposite failure modes.",
      ["The same failed status, but only after the subagent itself retries each filing five times with exponential backoff.", "Access denials are not transient, so backoff wastes time, and the coordinator still cannot see the five completed analyses."],
      ["A success status with the five analyses, silently omitting the three paywalled filings from the result list.", "Omitting failures as if coverage were complete hides three missing filings from the coordinator and the final report."],
      ["An exception raised to the top-level handler so the research run stops and an operator investigates the archive.", "Stopping the run discards five completed analyses when the coordinator could proceed with them and seek another source."],
      ["The five analyses, plus each failed filing marked `access_denied` and non-retryable, with any alternative source.", "Category and retryability tell the coordinator not to retry, partial results stay usable, and alternatives enable recovery."]),
    item("compaction-index", "5.4", "context", "Memory leak investigation",
      "A cross-package investigation of a memory leak has run 3 hours. Before the next compaction, the engineer needs to keep two verified allocation paths, one disproven theory about the cache layer, and 4 files still to inspect. Last time compaction ran, the next turns re-read 23 files already ruled out. How should the investigation state be carried forward?",
      "a", "For long investigations, keep conclusions outside the conversation: a scratchpad file of verified findings, rejected hypotheses and remaining work, which survives compaction and can be reloaded. Guide `/compact` toward what matters, delegate verbose exploration to subagents, and avoid restarting or refilling context with raw files.",
      ["Save verified paths, the disproven theory and pending files to `investigation.md`, then run a focused `/compact`.", "A scratchpad file survives any compaction, and focused /compact instructions keep the key findings in the summarized context too."],
      ["Run `/clear` and restart the investigation from the original bug report so the context starts fresh.", "Clearing discards three hours of verified findings and the disproven theory, so the dead ends will be explored again."],
      ["Ask Claude to state its confidence in the current leak theory so the next phase knows where to focus.", "A confidence statement records neither the evidence behind the verified paths nor the reasons the cache theory was rejected."],
      ["Paste the contents of all 23 previously read files into a new prompt so that nothing from the investigation is lost.", "Re-injecting raw files consumes the context compaction was freeing and gives no manifest of what was concluded."]),
    item("confidence-audit", "5.5", "eval", "Invoice extraction review",
      "An extractor auto-posts any field with confidence above 0.9. On a 500-document labeled set, accuracy above 0.9 is 99.2% for invoice numbers but 81% for handwritten amounts. The team can add 100 review slots a week and wants to catch new error types early. What should determine which fields go to review?",
      "c", "Model confidence must be calibrated against labeled outcomes, and calibration differs by field and document type. Set routing thresholds per segment using measured accuracy, send low-accuracy segments to review, and keep a stratified audit of auto-accepted output to catch errors the current thresholds miss.",
      ["A single higher threshold of 0.97 for all fields, validated so the review queue stays under 100 a week.", "A global cutoff ignores that confidence means different things per field, so handwritten amounts may still pass above it."],
      ["Equal review slots per field type, drawn from each field's lowest-confidence results and compared with labeled outcomes.", "Equal allocation spends slots on invoice numbers that are 99.2% accurate, starving the field with the evidenced problem."],
      ["Per-field thresholds calibrated on the labeled set, with handwritten amounts routed to review and a stratified audit.", "Calibrating by field uses observed accuracy, and the audit sample detects new error types in fields currently trusted."],
      ["Agreement between two extraction runs, auto-posting a field only when both runs return the identical value.", "Two runs of the same extractor share systematic misreads, so agreement can confirm the very errors the audit found."]),
    item("conflicting-estimates", "5.6", "research", "Transit market research",
      "A market-sizing report's synthesis subagent receives two figures for the same city: 420,000 monthly riders from a transit agency's 2024 fare-card count, and 560,000 from a 2025 consultancy survey estimate. The draft says 'about 490,000 riders (two sources)'. A reviewer must be able to trace the figure. How should the report present it?",
      "b", "When sources disagree, keep each value attached to its source, date and method and explain the difference, rather than averaging, choosing the newer figure, or presenting an unlabeled range. Many apparent conflicts come from different methods or periods, and readers need that context to judge them.",
      ["Keep the 490,000 average and cite both sources in a footnote as the basis for the combined estimate.", "The figures differ in year and method, so their average describes no actual measurement, and the citation hides that."],
      ["Report both figures with their source, year and method, and note the methodological difference explaining the gap.", "Keeping each figure with its provenance lets readers see why they differ and lets the reviewer trace each one."],
      ["Use the 560,000 figure because the 2025 survey is newer, citing the 2024 fare-card count as corroborating evidence.", "A newer estimate is not automatically more accurate, and a different, lower count does not corroborate it."],
      ["Report a range of 420,000 to 560,000 riders with no labels, which avoids choosing between the sources.", "An unlabeled range hides that one end is a measured count and the other a survey estimate from a different year."]),
    item("arch-practice-mill-approval", "1.5", "hooks", "Plant maintenance agent",
      "A maintenance agent's read-only `get_inspection` returns timestamps in each plant's local time, and 6% of schedules last month landed an hour off around daylight-saving changes. Its `schedule_repair` tool must execute only with a supervisor approval bound to that shift and work order; twice an approval for one shift was reused for another. Which two hook configurations fit?",
      "bd", "Use PreToolUse to enforce conditions that must hold before an action executes, such as an approval bound to the specific operation, and PostToolUse to normalize what a tool returned before the model reasons over it. Neither post-execution cancellation nor session-level snapshots provide per-action guarantees.",
      ["A PostToolUse hook on `schedule_repair` that cancels any repair scheduled without a matching shift approval.", "The repair is already scheduled when PostToolUse runs; cancelling afterward is compensation that may follow notifications or dispatch."],
      ["A PreToolUse hook on `schedule_repair` that denies the call unless the approval matches this shift and work order.", "Checking the approval binding before execution stops reused approvals deterministically; the scheduling service should enforce the same rule."],
      ["A PostToolUse hook on `get_inspection` that adds an approval flag whenever the inspection date matches the shift.", "A date coincidence is not a supervisor's approval, so this would manufacture authorization the policy requires a person to give."],
      ["A PostToolUse hook on `get_inspection` that converts timestamps to UTC using each plant's time zone, keeping the original.", "Normalizing the returned timestamp before Claude reads it removes the daylight-saving errors, and the original stays for audit."],
      ["A SessionStart hook that records the morning's approvals and reuses them for every repair in that session.", "Approval belongs to a specific shift and work order; reusing a session-wide snapshot is exactly how approvals were misapplied."]),
    item("arch-practice-mcp-scope", "2.4", "mcpConfig", "Documentation MCP server",
      "The repository's `.mcp.json` defines a `docs` server pointing at the team's v2 endpoint. One maintainer still gets v1 results; `claude mcp get docs` on her machine reports a local-scope entry in `~/.claude.json`, added months ago. A new teammate gets v2 correctly. What explains the difference, and what should the maintainer change?",
      "a", "When the same MCP server name exists in several scopes, Claude Code uses one definition by precedence, local over project over user, with no merging. A stale personal entry can silently shadow the shared project server. Inspect with `claude mcp get` and remove or rename the personal entry rather than changing the shared configuration.",
      ["Remove her local-scope `docs` entry with `claude mcp remove`, since local scope overrides the project definition.", "Same-named servers resolve local over project over user without merging, so removing the stale local entry lets the shared v2 one apply."],
      ["Update the `.mcp.json` entry to v2 again and commit it, since the project file overrides personal definitions on every machine.", "The project entry is already correct; local scope takes precedence over project scope, so recommitting changes nothing for her."],
      ["Add the v2 endpoint to `CLAUDE.md` and tell Claude to prefer it whenever both `docs` servers are available.", "Only one `docs` definition is active, chosen by scope precedence, and CLAUDE.md text does not configure MCP servers."],
      ["Rename the project server to `docs-v2` in `.mcp.json` so every teammate updates their prompts and references.", "Renaming works around one person's stale entry by forcing changes on everyone, and leaves the stale v1 server in place."]),
    item("arch-practice-skill-owner", "3.2", "skills", "Release notes skill",
      "The `/deploy-notes` skill drafts release notes and posts them to the team channel. Engineers want to run it by typing the command, but in 5 of 40 sessions Claude invoked it on its own while reviewing unrelated changes and posted drafts. The skill lives in `.claude/skills/deploy-notes/SKILL.md`. Which frontmatter change fits?",
      "a", "SKILL.md frontmatter controls who can invoke a skill. `disable-model-invocation: true` makes it manual-only; `user-invocable: false` hides it from people but lets Claude load it. `allowed-tools` pre-approves tools rather than restricting them, and `context: fork` changes where it runs, not who starts it.",
      ["Add `disable-model-invocation: true` so the skill runs only when an engineer types `/deploy-notes` themselves.", "This keeps the manual command and stops Claude from loading the skill on its own, which is the exact boundary requested."],
      ["Add `user-invocable: false` and reword the description so Claude understands the skill is meant for engineers only.", "user-invocable: false hides the command from people, the opposite direction, and a description change cannot block model invocation."],
      ["Add `allowed-tools: Read` so the skill cannot post to the channel unless an engineer approves the call.", "allowed-tools pre-approves listed tools; it neither stops Claude from invoking the skill nor removes the posting tool."],
      ["Add `context: fork` so the skill runs in a subagent and its drafts stay out of the main session.", "Forking isolates context but Claude can still choose to invoke the skill, so unrequested drafts would still be posted."]),
    item("arch-practice-label-import", "4.5", "batch", "Product catalog staging",
      "A staff portal must confirm a product label within 1 second. Separately, 3,200 anonymized catalog entries must be parsed by tomorrow and written to a database after per-entry validation. Last week's prototype joined batch results to entries by array index, and 41 records were saved against the wrong product. Which design meets the timing and attribution requirements?",
      "d", "Use synchronous Messages calls for latency-bound interactive work and Message Batches for large, latency-tolerant jobs. Batch results can return in any order, so set a meaningful custom_id on each request and join on it before validation and writes; positional joins attach results to the wrong records.",
      ["Put both workloads in Message Batches and stream the label's batch status to the staff portal until it finishes.", "Batches give no latency guarantee and can take hours, so streaming status cannot deliver a confirmed label within one second."],
      ["Send all 3,200 entries in one streaming Messages call and release each label as its first text delta arrives.", "A single huge call couples every entry's fate, and early deltas are incomplete outputs rather than validated labels."],
      ["Use live calls for labels and a batch for the catalog, keeping the index join but sorting results first.", "Splitting workloads is right, but batch results are not tied to submission order, so sorting cannot restore correct attribution."],
      ["Keep label checks synchronous; batch catalog entries with `custom_id` set to each product ID and join on it.", "Synchronous calls meet the one-second need, and custom_id joins tie each result to its product whatever the return order."]),
    item("arch-practice-calibrate-evidence", "5.6", "grounding", "Water utility reporting",
      "A synthesis subagent writes 'District 4 used 27 million liters in April'. Two sources contain the number 27: source W-4, an April invoice ledger for District 4, and source W-9, a summer forecast for a different basin. The draft cites both as independent confirmation. The report must let a reviewer reproduce each claim. What should the coordinator publish?",
      "b", "Citations must support the specific claim, not just contain the same number. Map each claim to the source that actually measures it and keep its scope, period and method; coincidentally matching figures from different populations are not corroboration, and uncited claims cannot be reproduced.",
      ["The claim citing both W-4 and W-9, since two sources reporting the same figure strengthen the statement.", "W-9 measures a different basin and period, so the matching number is coincidence, not independent confirmation of April use."],
      ["The claim citing only W-4, with its April period, District 4 scope and invoice-based method stated.", "The claim maps to the one source that measures it, with the context a reviewer needs to reproduce the figure."],
      ["The claim citing W-9 because the forecast is newer, noting that it is consistent with recent observed use.", "A forecast for another basin neither observes April use nor covers District 4, so it cannot support the claim."],
      ["The claim with no citation, keeping W-4 and W-9 in the internal handoff notes for anyone who asks.", "Without a claim-level citation, readers cannot tell which source supports the published figure or reproduce it."]),
  ],
  followup: [
    item("meter-tool-turn", "1.1", "stop", "Utility billing agent",
      "A utility billing agent responds with text 'Checking your meter reading now.' and a `get_meter_reading` tool_use block, with `stop_reason: \"tool_use\"`. The harness shows the text to the customer and ends the turn; 11% of 'what is my reading?' chats end with no reading given. The tool itself returns in 300 ms. What should the harness do next?",
      "c", "A tool_use stop reason means Claude has paused to wait for tool results, even if the response also contains text. Execute the tools, append the assistant message as returned plus matching tool_result blocks, and call the API again; only end_turn signals that the answer is complete.",
      ["Show the preamble as the final answer and record the meter reading so staff can send it to the customer later.", "The customer asked for the reading now; ending the turn on a preamble leaves the request unanswered."],
      ["Replace the assistant turn with a plain-text user message recording the reading and start a new request.", "Dropping the assistant turn breaks the tool_use link, so the API rejects it or Claude loses why the reading was fetched."],
      ["Run the tool, append the assistant turn and a matching `tool_result`, and call the API again until `end_turn`.", "tool_use means Claude is waiting for an observation; returning the linked result lets it answer, and end_turn marks completion."],
      ["Wait for the current response to finish with `end_turn` before running the tool and sending its result back.", "That response has already ended with tool_use; no end_turn will arrive until the tool result is sent in a new request."]),
    item("completed-or-disconnected", "2.2", "mcp", "Supplier catalog tool",
      "A supplier-catalog MCP tool currently returns `{\"items\": []}` with `isError: false` when the supplier API times out, and the same shape when a search truly finds nothing. Last month 64 agent replies told buyers 'no stock' during outages. You maintain the tool. How should it report the timeout?",
      "a", "A tool should report execution failures as tool results with isError: true and machine-readable detail, such as category, retryability and what was attempted, so the agent can tell an outage from a genuine empty result. Empty successes mislead, protocol errors hide context, and generic messages block recovery decisions.",
      ["Return a tool result with `isError: true`, `errorCategory: \"transient\"`, `isRetryable: true` and the attempted query.", "The agent can now tell an outage from a real empty result and decide whether to retry, all within a normal tool result."],
      ["Keep returning an empty list but add 'supplier timed out' to the text content so the model might notice the outage there.", "isError stays false, so clients and the agent can still treat the response as a successful empty search."],
      ["Return a JSON-RPC protocol error for timeouts so the MCP client rejects the call before the model sees it.", "Protocol errors are for malformed requests or unknown tools; the model loses the context it needs to explain or retry."],
      ["Return `isError: true` with the message 'Error' so the agent treats every failure the same and escalates.", "A generic error flags the failure but hides that it is transient and retryable, so the agent cannot choose a sensible recovery."]),
    item("scope-receipts", "3.3", "memory", "Payments and refunds services",
      "A receipt-formatting rule must load for `services/payments/**/*.receipt.test.ts` and `services/refunds/**/*.receipt.test.ts` but not for feature files in those services. The current `.claude/rules/receipts.md` has `paths: [\"services/**\"]`, and `/context` shows it loaded in 46 of 50 feature-only sessions. The team wants one file to maintain. Which change fits?",
      "d", "Path-scoped rules load whenever Claude touches a file matching any `paths` glob, so an overly broad glob behaves almost like an unscoped rule. Write globs that match the intended files exactly, using brace expansion for several directories, and confirm with `/context` that the rule stays out of unrelated sessions.",
      ["Keep `paths: [\"services/**\"]` and add a heading asking Claude to ignore the rule outside receipt tests.", "The broad glob still loads the rule for every file under services; a heading cannot prevent loading."],
      ["Move the rule into each service's `CLAUDE.md`, scoped so it loads only when Claude works on tests inside those two separate services.", "Directory CLAUDE.md files load for any file in the service, including feature files, and create two copies to maintain."],
      ["Move the rule to `~/.claude/rules/receipts.md` so it applies only to the engineer who writes most of the team's receipt tests.", "User-level rules are personal and not shared, so teammates writing receipt tests would lose the rule entirely."],
      ["Narrow `paths` to `\"services/{payments,refunds}/**/*.receipt.test.ts\"` so that the rule matches just those files in both services.", "Brace expansion covers both services in one glob, and the file-name pattern excludes feature files that the broad glob caught."]),
    item("membership-shape", "4.3", "structured", "Membership plan extraction",
      "An extraction call offers two tools, `extract_individual_plan` and `extract_family_plan`, with `tool_choice: {\"type\": \"auto\"}`; 6% of responses are prose. Separately, family plans must carry an `expires_on` date according to the membership registry, but the schema marks it nullable because individual plans may omit it. Which two changes belong in the pipeline?",
      "be", "Use `tool_choice: any` when several extraction schemas are offered and the response must be one of them; force a named tool only when one schema always applies. Rules that depend on authoritative data beyond the schema, such as a registry requirement, need validation in code after extraction.",
      ["Force `tool_choice` to `extract_family_plan` by name so every response is extracted with the family schema.", "Forcing one named tool removes prose replies but makes individual plans fit the wrong schema."],
      ["Set `tool_choice: {\"type\": \"any\"}` so Claude must call one of the two extraction tools and picks the fitting schema.", "any requires a tool call while letting Claude choose which schema matches the document, eliminating the 6% prose replies."],
      ["Remove `expires_on` from both schemas and ask Claude to mention the date in a free-text notes field.", "Moving a required date into free text loses type checking and makes the registry rule harder to apply."],
      ["Ask Claude to state whether its extracted expiry date follows the registry rule and accept a 'yes'.", "Self-assessment is not a deterministic check against the authoritative registry, so missing family expiry dates could still pass."],
      ["Validate each family plan's `expires_on` against the registry entry in code before saving the record.", "The schema allows null for individual plans, so a separate registry check enforces the family-plan requirement the schema cannot."]),
    item("coverage-shift", "5.3", "research", "Flood planning research",
      "A flood-planning coordinator's road subagent verified 14 closures. The tide subagent returned readings for 3 of 5 stations and, for stations 4 and 5, `error: \"sensor_api_timeout\", attempts: 2, retry_budget_exhausted: true`. The emergency briefing is due now and closures are independently actionable. How should the coordinator present the evidence?",
      "b", "At a deadline, synthesize verified findings and carry forward coverage gaps with what recovery was attempted. Do not imply checks that did not complete, substitute stale data as current, or hold independent verified findings back because another part of the work failed.",
      ["Report that all five stations were checked and list the three readings, since the other two returned no data at all.", "Stations 4 and 5 timed out; presenting them as checked implies coverage and readings that do not exist."],
      ["Report the 14 closures and 3 tide readings, and mark stations 4 and 5 unavailable after two timed-out attempts.", "Verified findings go out on time, and the explicit gap tells planners which stations still lack current readings."],
      ["Withhold the 14 closures until the tide subagent can retry stations 4 and 5 with a fresh budget.", "Closures are independently actionable, so delaying them for two tide stations holds back verified safety information."],
      ["Fill stations 4 and 5 with last week's readings and present the five-station set as current tide data.", "Week-old readings are not current evidence during a flood, and presenting them as current misleads the briefing."]),
  ],
};
